---@class LuckyBlockConfig
local LuckyBlockConfig = T(Global, "LuckyBlockConfig")

---@type [number, LuckyBlockPoolItem[]]
local LuckyBlockPool = {}
local LuckyBlockPoolItems = {}
---@type [string, LuckyBlock]
local LuckyBlocks = {}

function LuckyBlockConfig:init()
    local blockConfig = FileUtil.getGameConfigFromCsv("lucky_block/BlockSetting.csv")
    for i, v in pairs(blockConfig) do
        ---@class LuckyBlock
        local item = {}
        item.id = tonumber(v.id)
        item.poolId = v.poolId
        item.blockId = v.blockId
        LuckyBlocks[item.blockId] = item
    end

    local poolConfig = FileUtil.getGameConfigFromCsv("lucky_block/BlockGoodsPool.csv")
    for _, config in pairs(poolConfig) do
        ---@class LuckyBlockPoolItem
        local item = {}
        item.id = tonumber(config.id)
        item.itemId = tonumber(config.itemId)
        item.itemMeta = tonumber(config.itemMeta) or 0
        item.poolId = tonumber(config.poolId) or 0
        item.count = tonumber(config.count) or 1
        item.weight = tonumber(config.weight) or 0
        LuckyBlockPoolItems[item.id] = item
        if item.poolId ~= 0 then
            if not LuckyBlockPool[tostring(item.poolId)] then
                LuckyBlockPool[tostring(item.poolId)] = {}
            end
            table.insert(LuckyBlockPool[tostring(item.poolId)], item)
        end
    end
end

function LuckyBlockConfig:getBlockById(id)
    return LuckyBlocks[tostring(id + 1000)]
end

function LuckyBlockConfig:randomGoods(poolId, num)
    local pool = LuckyBlockPool[tostring(poolId)]
    if not pool then
        print("can't find block goods pool [poolId]:" .. poolId)
        return {}
    end
    local result = RandomUtil:randomItemByWeight(num, pool, false)
    return result
end

LuckyBlockConfig:init()

return LuckyBlockConfig